"""Promo codes: their definition, registration, validity period and usage limit.

:class:`PromoCode` describes a discount. :class:`PromoRegistry` keeps the codes, checks
that a code exists, is inside its validity period and is under its usage limit, and
counts successful uses. How a discount is spread over the lines of an order is decided
in :mod:`shop.pricing`.
"""

from __future__ import annotations

import logging
from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal
from enum import StrEnum

from .catalog import Category, normalize_key
from .clock import Clock, SystemClock
from .errors import PromoConditionsError, PromoExpiredError, UnknownPromoCodeError, ValidationError
from .money import ZERO, quantize_money

logger = logging.getLogger(__name__)

MAX_PERCENT = Decimal("100")


class DiscountKind(StrEnum):
    PERCENT = "percent"
    FIXED = "fixed"
    FREE_SHIPPING = "free_shipping"


@dataclass(frozen=True)
class PromoCode:
    """A promo code. ``value`` is a percentage for PERCENT, rubles for FIXED, zero for FREE_SHIPPING.

    ``max_discount`` caps a PERCENT discount in rubles. ``max_uses_per_customer`` limits the
    uses by one customer; it needs a ``customer_id`` at checkout.
    """

    code: str
    kind: DiscountKind
    value: Decimal
    min_order_amount: Decimal = ZERO
    excluded_categories: frozenset[Category] = frozenset()
    starts_at: datetime | None = None
    expires_at: datetime | None = None
    max_uses: int | None = None
    max_discount: Decimal | None = None
    max_uses_per_customer: int | None = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "code", normalize_key(self.code))
        if not self.code:
            raise ValidationError("promo code must not be empty")
        if not isinstance(self.kind, DiscountKind):
            raise ValidationError(f"discount kind of {self.code} must be a DiscountKind")
        _check_decimal(self.value, f"value of {self.code}")
        if self.kind is DiscountKind.PERCENT:
            if not ZERO < self.value <= MAX_PERCENT:
                raise ValidationError(f"percent of {self.code} must be in (0, 100]")
        elif self.kind is DiscountKind.FIXED:
            if self.value <= 0:
                raise ValidationError(f"fixed discount of {self.code} must be positive")
            _check_kopecks(self.value, f"fixed discount of {self.code}")
        else:
            if self.value != ZERO:
                raise ValidationError(f"free shipping of {self.code} must have value 0")

        _check_decimal(self.min_order_amount, f"minimum order amount of {self.code}")
        if self.min_order_amount < 0:
            raise ValidationError(f"minimum order amount of {self.code} must not be negative")
        _check_kopecks(self.min_order_amount, f"minimum order amount of {self.code}")

        excluded = frozenset(self.excluded_categories)
        if not all(isinstance(category, Category) for category in excluded):
            raise ValidationError(f"excluded categories of {self.code} must be Category values")
        object.__setattr__(self, "excluded_categories", excluded)

        for label, moment in (("starts_at", self.starts_at), ("expires_at", self.expires_at)):
            if moment is not None and (moment.tzinfo is None or moment.utcoffset() is None):
                raise ValidationError(f"{label} of {self.code} must be an aware datetime")
        if self.starts_at is not None and self.expires_at is not None:
            if self.starts_at >= self.expires_at:
                raise ValidationError(f"promo code {self.code} must start before it expires")

        if self.max_uses is not None:
            if isinstance(self.max_uses, bool) or not isinstance(self.max_uses, int):
                raise ValidationError(f"max_uses of {self.code} must be an integer")
            if self.max_uses < 1:
                raise ValidationError(f"max_uses of {self.code} must be at least 1")

        if self.max_discount is not None:
            _check_decimal(self.max_discount, f"max_discount of {self.code}")
            if self.kind is not DiscountKind.PERCENT:
                raise ValidationError(f"max_discount of {self.code} applies only to percent discounts")
            if self.max_discount <= ZERO:
                raise ValidationError(f"max_discount of {self.code} must be positive")
            _check_kopecks(self.max_discount, f"max_discount of {self.code}")

        if self.max_uses_per_customer is not None:
            if isinstance(self.max_uses_per_customer, bool) or not isinstance(self.max_uses_per_customer, int):
                raise ValidationError(f"max_uses_per_customer of {self.code} must be an integer")
            if self.max_uses_per_customer < 1:
                raise ValidationError(f"max_uses_per_customer of {self.code} must be at least 1")


def _check_decimal(amount: object, label: str) -> None:
    if not isinstance(amount, Decimal) or not amount.is_finite():
        raise ValidationError(f"{label} must be a finite Decimal")


def _check_kopecks(amount: Decimal, label: str) -> None:
    if quantize_money(amount) != amount:
        raise ValidationError(f"{label} has more than two fractional digits")


class PromoRegistry:
    """In-memory registry of promo codes and their successful-use counters.

    ``resolve`` checks in this order: the code exists, the validity period
    ``[starts_at, expires_at)`` contains the current time, the usage limit is not reached.
    """

    def __init__(self, clock: Clock | None = None) -> None:
        self._clock = clock or SystemClock()
        self._promos: dict[str, PromoCode] = {}
        self._uses: dict[str, int] = {}

    def add(self, promo: PromoCode) -> None:
        if promo.code in self._promos:
            raise ValidationError(f"duplicate promo code: {promo.code}")
        self._promos[promo.code] = promo
        self._uses[promo.code] = 0
        logger.debug("promo: registered %s", promo.code)

    def resolve(self, code: str) -> PromoCode:
        """Return the promo code if it can be used right now, otherwise raise."""
        promo = self._find(code)
        now = self._clock.now()
        if promo.starts_at is not None and now < promo.starts_at:
            raise PromoExpiredError(f"promo code {promo.code} starts at {promo.starts_at.isoformat()}")
        if promo.expires_at is not None and now >= promo.expires_at:
            raise PromoExpiredError(f"promo code {promo.code} expired at {promo.expires_at.isoformat()}")
        if promo.max_uses is not None and self._uses[promo.code] >= promo.max_uses:
            raise PromoConditionsError(f"promo code {promo.code} has no uses left")
        return promo

    def uses(self, code: str) -> int:
        return self._uses[self._find(code).code]

    def consume(self, code: str) -> None:
        """Count one successful use. Runs the same checks as :meth:`resolve`."""
        promo = self.resolve(code)
        self._uses[promo.code] += 1
        logger.debug("promo: %s used %d time(s)", promo.code, self._uses[promo.code])

    def release(self, code: str) -> None:
        """Undo one successful use, e.g. when an order is cancelled. No time or limit checks."""
        promo = self._find(code)
        if self._uses[promo.code] == 0:
            raise ValidationError(f"promo code {promo.code} has no uses to release")
        self._uses[promo.code] -= 1

    def _find(self, code: str) -> PromoCode:
        try:
            return self._promos[normalize_key(code)]
        except KeyError:
            raise UnknownPromoCodeError(code) from None

"""Order total calculation: line amounts, tax and shipping.

Rules (see README):

* line amount = unit price x quantity;
* tax is charged on top of the price, per line, at the rate of the line's category,
  and rounded per line (ROUND_HALF_UP); the order tax is the sum of line taxes;
* shipping is a flat fee, free when the goods subtotal reaches the threshold;
  carts with gift cards only are not shipped at all;
* shipping is not taxed;
* a promo code discounts only the participating lines (not gift cards, not excluded
  categories). The discount is split over those lines in whole kopecks, so the line
  discounts add up to the order discount exactly. Tax is charged on the discounted
  amount, and the free shipping threshold is compared with the goods after discount.
"""

from __future__ import annotations

import logging
from collections.abc import Mapping
from dataclasses import dataclass, field
from decimal import Decimal
from types import MappingProxyType

from .catalog import Cart, Category
from .errors import EmptyCartError, PromoConditionsError, ValidationError
from .money import CENT, ZERO, quantize_money, sum_money
from .promo import DiscountKind, PromoCode

logger = logging.getLogger(__name__)

DEFAULT_TAX_RATE = Decimal("0.20")
DEFAULT_TAX_RATES: Mapping[Category, Decimal] = MappingProxyType(
    {
        Category.BOOKS: Decimal("0.10"),
        Category.FOOD: Decimal("0.10"),
        Category.GIFT_CARD: Decimal("0"),
    }
)


@dataclass(frozen=True)
class TaxPolicy:
    rates: Mapping[Category, Decimal] = field(default_factory=lambda: DEFAULT_TAX_RATES)
    default_rate: Decimal = DEFAULT_TAX_RATE

    def __post_init__(self) -> None:
        for rate in (*self.rates.values(), self.default_rate):
            if not Decimal("0") <= rate < Decimal("1"):
                raise ValidationError(f"tax rate out of range: {rate}")

    def rate_for(self, category: Category) -> Decimal:
        return self.rates.get(category, self.default_rate)

    def tax_for(self, category: Category, taxable_amount: Decimal) -> Decimal:
        return quantize_money(taxable_amount * self.rate_for(category))


@dataclass(frozen=True)
class ShippingPolicy:
    fee: Decimal = Decimal("299.00")
    free_threshold: Decimal | None = Decimal("3000.00")

    def __post_init__(self) -> None:
        if self.fee < 0:
            raise ValidationError("shipping fee must not be negative")
        if self.free_threshold is not None and self.free_threshold < 0:
            raise ValidationError("free shipping threshold must not be negative")

    def cost_for(self, goods_amount: Decimal, *, needs_delivery: bool) -> Decimal:
        if not needs_delivery:
            return ZERO
        if self.free_threshold is not None and goods_amount >= self.free_threshold:
            return ZERO
        return quantize_money(self.fee)


@dataclass(frozen=True)
class LineTotal:
    sku: str
    category: Category
    quantity: int
    unit_price: Decimal
    amount: Decimal
    tax: Decimal
    discount: Decimal = ZERO


@dataclass(frozen=True)
class OrderTotal:
    lines: tuple[LineTotal, ...]
    subtotal: Decimal
    shipping: Decimal
    tax: Decimal
    total: Decimal
    discount: Decimal = ZERO

    @property
    def items_count(self) -> int:
        return sum(line.quantity for line in self.lines)


DEFAULT_SHIPPING = ShippingPolicy()
DEFAULT_TAX = TaxPolicy()


def calculate_total(
    cart: Cart,
    shipping: ShippingPolicy | None = None,
    tax: TaxPolicy | None = None,
    *,
    promo: PromoCode | None = None,
) -> OrderTotal:
    """Calculate the totals of ``cart``. Pure function: does not modify the cart."""
    if cart.is_empty:
        raise EmptyCartError("cannot calculate total of an empty cart")
    shipping = shipping or DEFAULT_SHIPPING
    tax = tax or DEFAULT_TAX
    discounts = _allocate_discount(cart, promo)

    lines: list[LineTotal] = []
    for cart_line, discount in zip(cart.lines, discounts):
        product = cart_line.product
        amount = cart_line.amount
        lines.append(
            LineTotal(
                sku=product.sku,
                category=product.category,
                quantity=cart_line.quantity,
                unit_price=product.price,
                amount=amount,
                tax=tax.tax_for(product.category, amount - discount),
                discount=discount,
            )
        )

    subtotal = sum_money(line.amount for line in lines)
    discount_total = sum_money(line.discount for line in lines)
    needs_delivery = any(line.product.is_physical for line in cart.lines)
    shipping_cost = shipping.cost_for(subtotal - discount_total, needs_delivery=needs_delivery)
    tax_total = sum_money(line.tax for line in lines)
    total = subtotal - discount_total + shipping_cost + tax_total

    logger.debug(
        "total: subtotal=%s discount=%s shipping=%s tax=%s total=%s",
        subtotal,
        discount_total,
        shipping_cost,
        tax_total,
        total,
    )
    return OrderTotal(
        lines=tuple(lines),
        subtotal=subtotal,
        shipping=shipping_cost,
        tax=tax_total,
        total=total,
        discount=discount_total,
    )


def _allocate_discount(cart: Cart, promo: PromoCode | None) -> tuple[Decimal, ...]:
    """Discount of every cart line (same order as ``cart.lines``), summing to the order discount.

    Each participating line gets ``floor(discount * amount / base)`` kopecks, where ``base``
    is the amount of all participating lines. The leftover kopecks go one by one to the lines
    with the largest remainders; on equal remainders the earlier line in the cart wins.
    """
    if promo is None:
        return tuple(ZERO for _ in cart.lines)

    eligible = [
        index
        for index, cart_line in enumerate(cart.lines)
        if cart_line.product.category is not Category.GIFT_CARD
        and cart_line.product.category not in promo.excluded_categories
    ]
    if not eligible:
        raise PromoConditionsError(f"promo code {promo.code} applies to no lines of the cart")

    base = sum_money(cart.lines[index].amount for index in eligible)
    if base < promo.min_order_amount:
        raise PromoConditionsError(
